function check([nums], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== nums.length) return false;
  for (let i = 0; i < actual.length; i++) {
    if (!Number.isInteger(actual[i]) || actual[i] % 2 !== i % 2) return false;
  }
  // The answer must use exactly the same values as nums.
  const counts = new Map();
  for (const value of nums) counts.set(value, (counts.get(value) ?? 0) + 1);
  for (const value of actual) {
    const left = counts.get(value) ?? 0;
    if (left === 0) return false;
    counts.set(value, left - 1);
  }
  return true;
}

