function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 20000) return 'nums needs 2 to 20000 values.';
  if (nums.length % 2 !== 0) return 'nums must have an even length.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each value is an integer from 0 to 1000.';
  const evens = nums.filter(v => v % 2 === 0).length;
  if (evens * 2 !== nums.length) return 'Exactly half of the values must be even.';
  return null;
}

