function sortArrayByParityII(nums) {
  let odd = 1;

  for (let even = 0; even < nums.length; even += 2) {
    if (nums[even] % 2 === 0) {
      continue;
    }
    while (nums[odd] % 2 === 1) {
      odd += 2;
    }
    const temp = nums[even];
    nums[even] = nums[odd];
    nums[odd] = temp;
  }
  return nums;
}

