function sortArrayByParityII(nums) {
  const evens = nums.filter(v => v % 2 === 0);
  const odds = nums.filter(v => v % 2 === 1);
  const result = [];
  for (let k = 0; k < evens.length; k++) result.push(evens[k], odds[k]);
  return result;
}

