function generate(rand, size) {
  const half = size === 'large' ? 1000 : 1 + Math.floor(rand() * 5);
  const top = size === 'large' ? 1000 : rand() < 0.5 ? 6 : 1000;
  // A random value of the given parity between 0 and top.
  const pick = parity => 2 * Math.floor(rand() * (Math.floor((top - parity) / 2) + 1)) + parity;
  const values = [];
  for (let k = 0; k < half; k++) values.push(pick(0), pick(1));
  // Shuffle so the parities start out of place.
  for (let i = values.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  return [values];
}
